L000480	\title{Subexponential decay of local correlations from diffusion-limited dephasing}
L000481	
L000482	\author{Ewan McCulloch}
L000483	\thanks{E.M. and J.A.J. contributed equally to this work.}
L000484	\affiliation{Department of Electrical and Computer Engineering, Princeton University, Princeton, NJ 08544, USA}
L000485	
L000486	
L000487	\author{J. Alexander Jacoby}
L000488	\thanks{E.M. and J.A.J. contributed equally to this work.}
L000489	\affiliation{Department of Physics, Princeton University, Princeton, New Jersey 08544, USA}
L000490	
L000491	\author{Curt von Keyserlingk}
L000492	\affiliation{Department of Physics, King's College London, Strand WC2R 2LS, UK}
